ALTER TABLE "beacon"."organizations" ADD CONSTRAINT "organizations_id_tenants_id_fk" FOREIGN KEY ("id") REFERENCES "beacon"."tenants" ("id");

CREATE UNIQUE INDEX "single_agency_customer" ON "beacon"."organizations" ("is_agency_customer") WHERE "beacon"."organizations"."is_agency_customer" = true;

ALTER TABLE "beacon"."organizations" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "beacon"."organizations" FORCE ROW LEVEL SECURITY;

CREATE POLICY "founder_organization" ON "beacon"."organizations" FOR ALL TO beacon_founder USING ("beacon"."organizations"."id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK ("beacon"."organizations"."id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);

CREATE POLICY "customer_organization" ON "beacon"."organizations" FOR SELECT TO beacon_app USING ("beacon"."organizations"."id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid AND EXISTS (SELECT 1 FROM beacon.memberships m WHERE m.tenant_id = "beacon"."organizations"."id" AND m.user_id = NULLIF(current_setting('app.user_id', true), '')::uuid AND m.status = 'active'));

GRANT SELECT, INSERT, UPDATE, DELETE ON "beacon"."organizations" TO beacon_founder;

GRANT SELECT ON "beacon"."organizations" TO beacon_app;

