CREATE POLICY "customer_membership" ON "beacon"."memberships" FOR SELECT TO beacon_app USING ("beacon"."memberships"."tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid AND "beacon"."memberships"."user_id" = NULLIF(current_setting('app.user_id', true), '')::uuid AND "beacon"."memberships"."status" = 'active');

